ForgeSeatView Read(string name,string state,bool other){var meta=System.IO.File.ReadAllText(".tools/stack-target-preview-1007/native/"+name+"-result.json");var folder=System.Text.RegularExpressions.Regex.Match(meta,"\"folder\":\\s*\"([^\"]+)\"").Groups[1].Value;Check(meta.Contains("\"PASS\""),"Native evidence "+name);return JsonUtility.FromJson<ForgeSeatView>(System.IO.File.ReadAllText(folder+"/"+state+(other?"-other":"")+".json"));}
