void Click(GameObject root){Check(root!=null,"Missing ray root");var rect=(RectTransform)root.transform;var pos=RectTransformUtility.WorldToScreenPoint(null,rect.TransformPoint(rect.rect.center));var e=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=pos,button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};var hits=new List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(e,hits);Check(hits.Count>0&&hits[0].gameObject.transform.IsChildOf(root.transform),"Unblocked ray "+root.name);UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,e,UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler);}
Transform Tile(int id)=>GameObject.Find("ChoiceCard_"+id)?.transform;
UnityEngine.UI.Text Hint(int id)=>Tile(id)?.Find("TargetedBy/HintScroll/Content/Text")?.GetComponent<UnityEngine.UI.Text>();
GameObject Zone(int owner,int local,string name)=>UnityEngine.Object.FindObjectsByType<UnityEngine.UI.Button>(FindObjectsSortMode.None).Single(b=>b.name=="Pile_"+name&&b.transform.parent.name.Contains(owner==local?"PlayerBottomLeft":"OpponentTopRight")).gameObject;
