System.Collections.IEnumerator Validate(){
 GamePreferences.SetLanguage("zh-CN");float until=Time.realtimeSinceStartup+20;while(!GamePreferences.Ready&&Time.realtimeSinceStartup<until)yield return null;Check(GamePreferences.Ready,"Language ready");yield return Frame();int sent=0;
 foreach(int local in new[]{1,2})foreach(string zone in new[]{"坟场","放逐","牌库","手牌"}) {
  ui.Present(null,1,false,null,null,"");yield return Frame();var data=Input((zone=="放逐"?"exile":"grave")+(local==2?"-other":""));ui.Present(data,local,false,_=>sent++,null,"");yield return Frame();
  int owner=zone=="手牌"?local:2;
