  var panel=GameObject.Find("CardSelection");Check(panel!=null,"Zone entry missing "+zone);
  var actual=panel.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("ChoiceCard_")).Select(t=>int.Parse(t.name.Substring(11))).ToArray();
  var p=data.players[owner-1];var expected=zone=="坟场"?p.graveyardCards:zone=="放逐"?p.exileCards:zone=="手牌"?p.hand:Array.Empty<ForgeCardView>();
  Check(actual.OrderBy(x=>x).SequenceEqual(expected.Select(c=>c.id).OrderBy(x=>x)),"Zone exact IDs/filter "+zone);
  if(zone=="牌库")Check(panel.transform.Find("Empty")!=null,"Hidden library empty view");
  if(zone=="坟场")Check(actual.Distinct().Count()==2,"Same-name copies collapsed");
  var hint=actual.Select(Hint).FirstOrDefault(x=>x!=null);if(hint!=null)Check(hint.text.Contains("的目标（堆叠")&&!hint.text.Contains("的对象"),"Requested target wording");
  foreach(var art in panel.GetComponentsInChildren<UnityEngine.UI.Button>().Where(b=>b.name=="Artwork"))Check(art.interactable,"Readonly detail not enabled");
  Check(sent==0,"Browse submits");Click(GameObject.Find("CloseReviewCards"));yield return Frame();Check(GameObject.Find("CardSelection")==null,"Browser close failed");Pass("actual seat"+local+" "+zone+" entry/exact IDs/close/readonly");
 }
 foreach(string zone in new[]{"坟场","放逐"}) {
  ui.Present(null,1,false,null,null,"");yield return Frame();var data=Input("grave");if(zone=="坟场")data.players[1].graveyardCards=Array.Empty<ForgeCardView>();else data.players[1].exileCards=Array.Empty<ForgeCardView>();ui.Present(data,1,false,_=>sent++,null,"");yield return Frame();Click(Zone(2,1,zone));yield return Frame();Check(GameObject.Find("CardSelection").transform.Find("Empty")!=null,"Empty zone message");Click(GameObject.Find("CloseReviewCards"));yield return Frame();Pass("adapter empty "+zone+" close no submit");
 }
 ui.Present(null,1,false,null,null,"");yield return Frame();var known=Input("grave");var card=known.players[1].graveyardCards[0];known.players[1].hand=new[]{card};known.players[1].handCount=4;ui.Present(known,1,false,_=>sent++,null,"");yield return Frame();Click(GameObject.Find("OpponentPlate").transform.Find("Sub").gameObject);yield return Frame();Check(GameObject.Find("ChoiceCard_"+card.id)!=null&&GameObject.Find("CardSelection").GetComponentsInChildren<Transform>().Count(t=>t.name.StartsWith("ChoiceCard_"))==1,"Known hand subset");Check(GameObject.Find("CardSelection").transform.Find("Count").GetComponent<UnityEngine.UI.Text>().text=="4 张","Known hand total count");Pass("adapter opponent known hand subset only; total count separate");
 ui.Present(null,1,false,null,null,"");yield return Frame();var top=Input("grave");top.players[1].libraryTop=card;top.players[1].libraryTopPublic=true;ui.Present(top,1,false,_=>sent++,null,"");yield return Frame();Click(Zone(2,1,"牌库"));yield return Frame();Check(GameObject.Find("ChoiceCard_"+card.id)!=null&&GameObject.Find("CardSelection").GetComponentsInChildren<Transform>().Count(t=>t.name.StartsWith("ChoiceCard_"))==1,"Known top only");Pass("adapter known library top only");
 ui.Present(null,1,false,null,null,"");yield return Frame();var ended=Input("grave");var reviewOwner=ended.players[0];reviewOwner.reviewLibrary=reviewOwner.hand.Concat(reviewOwner.battlefield.Take(2)).ToArray();ended.awaitingInput=false;ended.request=null;ui.Present(ended,1,false,_=>sent++,null,"");yield return Frame();Click(Zone(1,1,"牌库"));yield return Frame();Check(GameObject.Find("CardSelection").GetComponentsInChildren<Transform>().Count(t=>t.name.StartsWith("ChoiceCard_"))==reviewOwner.reviewLibrary.Length,"End review library");Pass("adapter authorized own end-review library exact identities");
 ui.Present(null,1,false,null,null,"");yield return Frame();var multi=Input("two-sources-other");ui.Present(multi,2,false,_=>sent++,null,"");yield return Frame();Click(Zone(2,2,"坟场"));yield return Frame();var h=Hint(multi.players[1].graveyardCards[0].id);Check(h.text.Contains("的目标（堆叠1）")&&h.text.Contains("的目标（堆叠2）")&&h.preferredHeight<=h.transform.parent.parent.GetComponent<RectTransform>().rect.height+.1f,"New wording two sources fit");ScreenCapture.CaptureScreenshot(output+"/target-wording.png");yield return Frame();Pass("actual two-source requested Chinese wording and fit");
 // A new authoritative picker takes over an open browser, preserving native indices.
 var choice=Input("mixed-grave");int chosen=-1;ui.Present(choice,1,true,i=>{sent++;chosen=i;},null,"");yield return Frame();Check(GameObject.Find("CloseReviewCards")==null,"Browser controls leaked into picker");var option=choice.request.options.First(o=>o.card!=null&&!string.IsNullOrEmpty(o.card.name));Click(GameObject.Find("ChoiceCard_"+option.card.id).transform.Find("Artwork").gameObject);yield return Frame();Check(chosen==Array.IndexOf(choice.request.options,option)&&sent==1,"Actual grave picker submits native index");Check(!ui.TrySubmitPresentedOption(chosen,choice.request.requestId),"Duplicate submit");Pass("actual browser->picker handover/native exact ID/duplicate guard");
 // Original real fetch input offers only native legal cards; previews are dimmed and unclickable.
 ui.Present(null,1,false,null,null,"");yield return Frame();var fetch=Input("fetch");ui.Present(fetch,fetch.request.seat,true,i=>sent++,null,"");yield return Frame();var panel2=GameObject.Find("CardSelection");Check(panel2!=null,"Real fetch picker");foreach(var c in fetch.request.previewCards.Where(c=>c.selection=="不可选")){var tile=GameObject.Find("ChoiceCard_"+c.id);if(tile!=null)Check(tile.transform.Find("Artwork").GetComponent<UnityEngine.UI.Button>()==null,"Ineligible preview interactive");}Pass("actual fetch legal candidates and noncandidate previews separated");
 // All-ineligible is a UI adapter: real native no-match result separately proves native auto continuation.
 ui.Present(null,1,false,null,null,"");yield return Frame();var empty=Input("fetch");var preview=empty.request.previewCards.Where(c=>c.selection=="不可选").Take(3).ToArray();Check(preview.Length==3,"Need real ineligible previews");empty.request.previewCards=preview;empty.request.options=new[]{new ForgeOption{id="cancel",label="Cancel"}};empty.request.selectedCount=0;empty.request.minCount=0;empty.request.maxCount=1;int cancelled=0;ui.Present(empty,empty.request.seat,true,i=>{Check(i==0,"Cancel index");cancelled++;},null,"");yield return Frame();Check(GameObject.Find("CardSelection").GetComponentsInChildren<UnityEngine.UI.Button>().All(b=>b.name!="Artwork"),"All-ineligible card active");Click(GameObject.Find("SelectionAction_0"));yield return Frame();Check(cancelled==1,"All-ineligible cannot leave");Pass("adapter all-ineligible preview cards no selection, native cancel exits");
 ui.Present(empty,empty.request.seat,false,i=>cancelled++,null,"");yield return Frame();Check(!GameObject.Find("SelectionAction_0").GetComponent<UnityEngine.UI.Button>().interactable&&!ui.TrySubmitPresentedOption(0,empty.request.requestId),"Disabled input submits");ui.Present(empty,empty.request.seat,true,i=>cancelled++,null,"");yield return Frame();Check(!ui.TrySubmitPresentedOption(0,empty.request.requestId-1),"Stale request submits");Pass("adapter disabled-input and stale request guards");
 ui.Present(null,1,false,null,null,"");yield return Frame();ui.Present(Input("grave"),1,false,null,null,"");yield return Frame();Click(Zone(2,1,"坟场"));yield return Frame();var prior=GameObject.Find("ChoiceCard_"+Input("grave").players[1].graveyardCards[0].id);Click(prior.transform.Find("Artwork").gameObject);yield return Frame();Check(GameObject.Find("ReviewDetail")!=null,"Readonly detail");Check(sent==1,"Readonly submitted");Pass("actual readonly full card detail after picker cleanup; no submit");

 ui.Present(null,1,false,null,null,"");yield return Frame();var reveal=Input("native-no-match-reveal");int confirmed=-1;ui.Present(reveal,reveal.request.seat,true,i=>confirmed=i,null,"");yield return Frame();var revealPanel=GameObject.Find("CardSelection");Check(revealPanel!=null&&revealPanel.GetComponentsInChildren<UnityEngine.UI.Button>().All(b=>b.name!="Artwork"),"Native no-match reveal card wrongly selectable");var action=revealPanel.GetComponentsInChildren<UnityEngine.UI.Button>().Single(b=>b.name.StartsWith("SelectionAction_"));Click(action.gameObject);yield return Frame();Check(confirmed>=0&&reveal.request.options[confirmed].id=="confirm-cards","Native no-match confirmation cannot continue");Pass("actual no-match native RevealCards 60 readonly cards and confirmation index");
