System.Collections.IEnumerator Guard(){var frames=new Stack<System.Collections.IEnumerator>();frames.Push(Validate());System.IO.File.WriteAllText(output+"/result-all.txt","RUNNING");System.IO.File.WriteAllText(output+"/steps.log","");try{while(frames.Count>0){object next;try{var it=frames.Peek();if(!it.MoveNext()){(it as IDisposable)?.Dispose();frames.Pop();continue;}next=it.Current;if(next is System.Collections.IEnumerator child){frames.Push(child);continue;}}catch(Exception e){System.IO.File.WriteAllText(output+"/result-all.txt","FAIL "+e);throw;}yield return next;}System.IO.File.WriteAllText(output+"/result-all.txt","PASS bounded R15 region browse and candidate contracts; exact native identities, readonly/selection distinction, empty and all-ineligible adapters, actual zone entry/detail rays, requested target wording. Native no-match separately recorded; no new live network proof.");}finally{ui.Present(null,1,false,null,null,"");ui.enabled=previousEnabled;GamePreferences.SetLanguage(previousLanguage);for(int i=0;i<modules.Length;i++)if(modules[i]!=null)modules[i].enabled=mf[i];for(int i=0;i<notices.Length;i++)if(notices[i]!=null)notices[i].enabled=nf[i];}}
ui.StartCoroutine(Guard());

